'use client';

import Link from 'next/link';
import { Smartphone, Monitor, Server, Eye, Shield, ArrowRight } from 'lucide-react';

export default function Home() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900">
      <div className="container mx-auto px-4 py-16">
        {/* Header */}
        <div className="text-center mb-12">
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-red-500/20 mb-6">
            <Shield className="w-10 h-10 text-red-400" />
          </div>
          <h1 className="text-5xl font-bold text-white mb-4">
            PNW Logistics Hacker Hierarchy
          </h1>
          <p className="text-xl text-slate-400 max-w-2xl mx-auto">
            Demonstration of tiered authentication systems for different privilege levels
          </p>
        </div>

        {/* Tier Cards */}
        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6 max-w-7xl mx-auto mb-12">
          {/* Tier 1 - Reconnaissance */}
          <div className="bg-slate-800/50 backdrop-blur-lg rounded-xl border border-slate-700/50 p-6">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 rounded-lg bg-yellow-500/20">
                <Eye className="w-6 h-6 text-yellow-400" />
              </div>
              <div>
                <div className="text-xs font-semibold text-yellow-400 uppercase tracking-wider">Tier 1</div>
                <h3 className="text-lg font-bold text-white">Reconnaissance</h3>
              </div>
            </div>
            <p className="text-slate-400 text-sm mb-4">
              Public information gathering. No authentication required.
            </p>
            <div className="text-xs text-slate-500 space-y-1">
              <p>• Social media profiling</p>
              <p>• GPS signal observation</p>
              <p>• Public data collection</p>
            </div>
          </div>

          {/* Tier 2 - Driver Mobile App */}
          <Link href="/tier-2/login" className="bg-slate-800/50 backdrop-blur-lg rounded-xl border border-blue-500/30 hover:border-blue-500/60 p-6 transition-all duration-200 hover:shadow-lg hover:shadow-blue-500/20 group">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 rounded-lg bg-blue-500/20">
                <Smartphone className="w-6 h-6 text-blue-400" />
              </div>
              <div>
                <div className="text-xs font-semibold text-blue-400 uppercase tracking-wider">Tier 2</div>
                <h3 className="text-lg font-bold text-white">Driver Mobile App</h3>
              </div>
            </div>
            <p className="text-slate-400 text-sm mb-4">
              Low privilege access. In-app passkey authentication.
            </p>
            <div className="text-xs text-slate-500 space-y-1 mb-4">
              <p>• Own route data access</p>
              <p>• Delivery confirmations</p>
              <p>• Limited view scope</p>
            </div>
            <div className="flex items-center text-blue-400 text-sm font-medium group-hover:gap-2 transition-all">
              Access Login <ArrowRight className="w-4 h-4 ml-1" />
            </div>
          </Link>

          {/* Tier 3 - Dispatcher Dashboard */}
          <Link href="/tier-3/login" className="bg-slate-800/50 backdrop-blur-lg rounded-xl border border-purple-500/30 hover:border-purple-500/60 p-6 transition-all duration-200 hover:shadow-lg hover:shadow-purple-500/20 group">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 rounded-lg bg-purple-500/20">
                <Monitor className="w-6 h-6 text-purple-400" />
              </div>
              <div>
                <div className="text-xs font-semibold text-purple-400 uppercase tracking-wider">Tier 3</div>
                <h3 className="text-lg font-bold text-white">Dispatcher Dashboard</h3>
              </div>
            </div>
            <p className="text-slate-400 text-sm mb-4">
              Mid privilege access. WebAuthn passkey authentication.
            </p>
            <div className="text-xs text-slate-500 space-y-1 mb-4">
              <p>• All active routes</p>
              <p>• Driver locations</p>
              <p>• Route modifications</p>
            </div>
            <div className="flex items-center text-purple-400 text-sm font-medium group-hover:gap-2 transition-all">
              Access Login <ArrowRight className="w-4 h-4 ml-1" />
            </div>
          </Link>

          {/* Tier 4 - Admin Backend */}
          <Link href="/tier-4/login" className="bg-slate-800/50 backdrop-blur-lg rounded-xl border border-red-500/30 hover:border-red-500/60 p-6 transition-all duration-200 hover:shadow-lg hover:shadow-red-500/20 group">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 rounded-lg bg-red-500/20">
                <Server className="w-6 h-6 text-red-400" />
              </div>
              <div>
                <div className="text-xs font-semibold text-red-400 uppercase tracking-wider">Tier 4</div>
                <h3 className="text-lg font-bold text-white">Admin Backend</h3>
              </div>
            </div>
            <p className="text-slate-400 text-sm mb-4">
              Full administrative access. SSO passkey via password manager.
            </p>
            <div className="text-xs text-slate-500 space-y-1 mb-4">
              <p>• All historical data</p>
              <p>• System configurations</p>
              <p>• Full database access</p>
            </div>
            <div className="flex items-center text-red-400 text-sm font-medium group-hover:gap-2 transition-all">
              Access Login <ArrowRight className="w-4 h-4 ml-1" />
            </div>
          </Link>
        </div>

        {/* Info Section */}
        <div className="max-w-4xl mx-auto bg-slate-800/30 backdrop-blur-lg rounded-xl border border-slate-700/50 p-8">
          <h2 className="text-2xl font-bold text-white mb-4">Authentication Methods</h2>
          <div className="space-y-4 text-slate-300">
            <div className="flex gap-4">
              <Smartphone className="w-5 h-5 text-blue-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-semibold text-white mb-1">Tier 2: In-App Passkey</p>
                <p className="text-sm">Passkeys backed by device biometrics or hardware security keys, accessed directly within the mobile application.</p>
              </div>
            </div>
            <div className="flex gap-4">
              <Monitor className="w-5 h-5 text-purple-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-semibold text-white mb-1">Tier 3: WebAuthn Passkey</p>
                <p className="text-sm">Web Authentication API for passkey login, phishing-resistant and supported across major platforms.</p>
              </div>
            </div>
            <div className="flex gap-4">
              <Server className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-semibold text-white mb-1">Tier 4: SSO Passkey</p>
                <p className="text-sm">Single Sign-On enabled passkey stored in password manager, allowing access to multiple applications without additional authentication.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}